EN2 = {
"moda-01": ("How many dollars did the first Barbie doll cost when it launched in 1959?", "dollar|dollars", "The first Barbie, in a black-and-white striped swimsuit, cost exactly $3 in 1959. A mint one in its original box sold on eBay in 2004 for $3,552.", ""),
"moda-02": ("How many dollars was student Carolyn Davidson paid in 1971 for designing the Nike logo, the famous Swoosh?", "dollar|dollars", "Nike paid just $35 in 1971 for one of the world's best-known logos – Carolyn Davidson charged $2 an hour and spent 17.5 hours on it. The company later made it up to her with shares.", ""),
"moda-03": ("How many thousand dollars did a single ticket to the Met Gala, New York's most famous fashion night, cost in 2024?", "thousand dollars|thousand dollars", "A ticket to the 2024 Met Gala cost $75,000. And you can't turn up in just anything – Anna Wintour sets the dress code.", "Price per seat in 2024."),
"moda-04": ("How many pages did the September 2007 issue of American Vogue, the making of which is chronicled in the documentary The September Issue, have?", "page|pages", "The September 2007 Vogue had 840 pages and weighed almost five pounds. Even that wasn't the record – the September 2012 issue had 76 pages more.", ""),
"moda-05": ("How many ways of tying a necktie did physicists Thomas Fink and Yong Mao count in their book The 85 Ways to Tie a Tie (1999)?", "way|ways", "Two Cambridge physicists proved mathematically that, using the conventional method (wide end around the narrow end), a tie can be knotted in exactly 85 ways. Most people manage one.", "Using the conventional tying method as defined in the book."),
"moda-06": ("How many thousand dollars did a buyer pay in 2016 for the dress Marilyn Monroe wore to sing 'Happy Birthday, Mr. President' to JFK?", "thousand dollars|thousand dollars", "The sheer dress with 2,500 rhinestones sewn on sold at auction in 2016 for $4.8 million. In 2022 Kim Kardashian borrowed it for the Met Gala.", "$4,800,000, Los Angeles auction, 17 Nov 2016."),
"moda-07": ("How many thousand dollars did the Air Jordan 13s worn by Michael Jordan in the 1998 NBA Finals – the most expensive sneakers ever – sell for at auction in 2023?", "thousand dollars|thousand dollars", "The sneakers from the 'Last Dance' season sold in April 2023 for $2.2 million, a world record for a pair of sneakers.", "$2,200,000, Sotheby's, April 2023."),
"moda-08": ("How many dollars did a pair of 1880s Levi's jeans found in an abandoned mine sell for at auction in 2022?", "dollar|dollars", "The roughly 140-year-old jeans from an abandoned mine sold in New Mexico for $87,400. Levi Strauss and Jacob Davis patented riveted jeans on 20 May 1873.", "Auction in New Mexico, 2022."),
"moda-09": ("How many million pairs of Crocs had been sold worldwide from the company's founding up to 2017?", "million pairs|million pairs", "Loved and loathed in equal measure, Crocs sold 300 million pairs by 2017 – one pair for every 25 people on the planet.", "Cumulative sales from 2002 to 2017."),
"moda-10": ("Up to how many centimetres tall were the soles of Venetian chopines, the platform shoes worn by ladies in the 15th century?", "centimetre|centimetres", "Around 1430 Venetian chopines reached heights of up to 38 centimetres. Ladies needed attendants just to walk; a law later capped them at three inches, but nobody obeyed it.", "Maximum documented height around 1430."),
"moda-11": ("How many million dollars (hammer price, before fees) did Dorothy's ruby slippers from The Wizard of Oz sell for in December 2024?", "million dollars|million dollars", "The slippers, stolen from a museum in 2005 and recovered by the FBI 13 years later, sold in 2024 for $28 million ($32.5 million with fees) – the most expensive piece of movie memorabilia ever.", "Hammer price; $32.5 million including buyer's premium."),
"moda-12": ("How old was Kate Moss when she was discovered at JFK airport?", "year|years", "Kate Moss was spotted at New York's JFK airport in 1988 by the founder of Storm Model Management – she was 14 and on her way home from a holiday in the Bahamas.", ""),
"sport-01": ("How many minutes did the longest tennis match in history, John Isner vs Nicolas Mahut at Wimbledon 2010, last?", "minute|minutes", "Isner beat Mahut 6–4, 3–6, 6–7, 7–6, 70–68 after 11 hours and 5 minutes of play spread over three days. A total of 183 games were played, also a record.", "11 hours 5 minutes = 665 minutes of playing time; first round, Wimbledon 2010."),
"sport-02": ("How many rounds did the longest gloved boxing match in history, Andy Bowen vs Jack Burke in 1893, have?", "round|rounds", "The fight on 6 April 1893 lasted 7 hours 19 minutes, with three-minute rounds. For comparison, today's professional bouts have at most 12 rounds.", "Bowen vs Burke, 6 April 1893; 110 three-minute rounds."),
"sport-03": ("How many kilometres long was the route of the longest Tour de France ever, the 1926 edition?", "kilometre|kilometres", "The 1926 Tour had only 17 stages but covered 5,745 km – the route basically traced the borders of France. Modern editions are around 3,500 km.", "Total route length of the 1926 edition (17 stages)."),
"sport-04": ("How many points (goals plus assists) did Jaromír Jágr score in the NHL regular season over his career?", "point|points", "Jágr scored 766 goals and 1,155 assists, 1,921 points in all – in NHL history only Wayne Gretzky, with 2,857, is ahead of him.", "NHL regular season; career total 766 goals + 1,155 assists (2nd in NHL history)."),
"sport-05": ("How many goals did Australia score against American Samoa in 2002 World Cup qualifying, the biggest win in international football history?", "goal|goals", "The match on 11 April 2001 ended 31–0. Striker Archie Thompson scored 13 himself, also a world record for one player in an international match.", "2002 World Cup qualifying (Oceania), 11 April 2001."),
"sport-06": ("How many Grand Slam titles in total (singles, doubles and mixed doubles) did Martina Navratilova win?", "title|titles", "The Prague native collected 18 singles titles, a record 31 in women's doubles and 10 in mixed doubles – 59 in all, an Open Era record.", "Singles (18) + women's doubles (31) + mixed doubles (10)."),
"sport-07": ("How many kilometres long is the Self-Transcendence 3100 Mile Race, the longest certified footrace in the world?", "kilometre|kilometres", "The race is run every summer around a single block in Queens, New York – one lap is 883 metres and runners must complete it 5,649 times.", "3,100 miles = 4,989 km."),
"sport-08": ("How many million dollars was the total prize pool of The International 2021, the Dota 2 tournament?", "million dollars|million dollars", "The $40,018,195 prize pool – the largest in esports history at the time – was largely funded by players buying the in-game battle pass. Winners Team Spirit took home over $18 million.", "Exactly $40,018,195 (Wikipedia infobox); winners Team Spirit received $18,208,300."),
"sport-09": ("How many grams of pure gold must an Olympic gold medal contain at minimum under IOC rules?", "gram|grams", "A gold medal is actually at least 92.5% silver and only gold-plated – 6 grams is enough. Medals of solid gold were last handed out in 1912.", "Minimum under the IOC Olympic Charter; silver (min. 92.5%) plated with 6 g of gold."),
"sport-10": ("How many moves did the longest tournament chess game in history, played in Belgrade in 1989 by Ivan Nikolić and Goran Arsović, have?", "move|moves", "The game lasted over 20 hours and ended in a draw – the last 103 moves were a rook and bishop versus rook endgame.", "Tournament game, Belgrade 1989; drawn after 269 moves."),
"sport-11": ("How many millimetres is the diameter of a golf hole?", "millimetre|millimetres", "By the rules a golf hole is exactly 108 mm across – the ball is 43 mm, so only two and a bit would fit. It must be at least 10 cm deep.", ""),
"sport-12": ("How many centimetres above the floor is a basketball hoop?", "centimetre|centimetres", "The rim hangs 305 cm (10 feet) above the floor – the same as in 1891, when James Naismith nailed a peach basket to the gym balcony.", "Standard height in adult competition (3.05 m)."),
"sport-13": ("In how many hundredths of a second did Usain Bolt run his 100 m world record?", "hundredth of a second|hundredths of a second", "Usain Bolt ran 100 m in 9.58 seconds at the 2009 World Championships in Berlin. The record still stands – and by his own account he had run his previous one in Beijing with a shoelace untied.", "9.58 s, World Athletics Championships, Berlin 2009."),
"sport-14": ("How many Olympic medals in total did swimmer Michael Phelps win?", "medal|medals", "Michael Phelps collected 28 medals over four Olympics, 23 of them gold. If he were a country he would rank above most nations in the all-time gold table.", "Olympic Games 2004–2016."),
"sport-15": ("How many Grand Slam singles titles has Novak Djokovic won (as of 2026)?", "title|titles", "Novak Djokovic holds the men's record of 24 Grand Slam singles titles – two more than Nadal and four more than Federer.", "As of 2026."),
"sport-16": ("How many consecutive league matches did Arsenal go unbeaten in 2003–2004 (the 'Invincibles' run)?", "match|matches", "Arsène Wenger's Arsenal went through the entire 2003/04 season unbeaten and stretched the run to 49 league games. Manchester United ended it with a disputed penalty.", "Premier League, 2003–2004."),
"sport-17": ("How many seconds is the men's marathon world record, run by Sabastian Sawe in London in April 2026?", "second|seconds", "Sabastian Sawe ran the 2026 London Marathon in 1:59:30 – the first person under two hours in a regular race. That's an average of 2:50 per kilometre for 42 kilometres.", "1:59:30 = 7,170 s; as of 2026."),
"sport-18": ("How many centimetres is the high jump world record that Javier Sotomayor has held since 1993?", "centimetre|centimetres", "Cuba's Javier Sotomayor jumped 245 cm in Salamanca in 1993. The record has stood for over 30 years – longer than any other men's track and field record.", "2.45 m, Salamanca, 27 July 1993."),
"sport-19": ("How many points is a maximum break in snooker?", "point|points", "A maximum break is 147 points: 15 reds, a black after each, then all six colours. Only about two hundred players in history have made one in professional play.", "120 + 27 = 147 points."),
"sport-20": ("How many grams does the men's shot weigh in open shot put competition?", "gram|grams", "The men's shot weighs 7.26 kg (16 lb), the women's 4 kg. The world record is over 23 metres – like throwing it over a two-storey house lying on its side.", "7.26 kg."),
"sport-21": ("How many laps is the Indianapolis 500?", "lap|laps", "The Indy 500 is 200 laps of a 2.5-mile oval, i.e. 500 miles (800 km). By tradition the winner drinks milk instead of champagne.", ""),
"sport-22": ("How many kilometres long is the Vasaloppet, the oldest and biggest cross-country ski race?", "kilometre|kilometres", "The Vasaloppet runs 90 km from Sälen to Mora and has been held since 1922. It commemorates Gustav Vasa's flight from the Danes in 1520 – and over 15,000 skiers take it on every year.", ""),
"technologie-01": ("How many million characters did the world's first hard disk drive, the IBM 350 from 1956, hold?", "million characters|million characters", "The world's first hard drive, the IBM 350 from 1956, weighed about a ton and consisted of a stack of 24-inch platters – all for 5 million six-bit characters, roughly 3.75 MB. A single phone photo wouldn't fit.", "IBM 350 capacity (1956): 5 million 6-bit characters (≈ 3.75 MB)."),
"technologie-02": ("How many seconds did the first digital camera (Kodak, 1975) take to record one image to cassette tape?", "second|seconds", "The digital camera prototype built by Steven Sasson at Kodak in 1975 weighed 3.6 kg, shot at 100 × 100 pixels and took 23 seconds to write each image to a cassette tape.", "Steven Sasson's prototype (Eastman Kodak, 1975); the source spells the number out ('twenty-three seconds')."),
"technologie-03": ("How many minutes of talk time did the first commercial mobile phone, the Motorola DynaTAC 8000X, offer on one charge?", "minute|minutes", "The Motorola DynaTAC 8000X, the first commercially sold mobile phone (1984), cost $3,995, weighed 790 grams and took about 10 hours to charge. The reward: a full 30 minutes of talk time.", "DynaTAC 8000X model (commercially available from 1984); talk time on a full charge."),
"technologie-04": ("In how many languages are the greetings recorded on the Voyager Golden Record?", "language|languages", "The Golden Record carried to the stars by Voyager 1 and 2 in 1977 holds images, sounds of Earth, music and greetings in 55 languages. Czech is among them – the Czechs wish the aliens all the best.", "Spoken greetings on the Voyager Golden Record (1977) according to NASA; Czech is among the languages."),
"technologie-05": ("How many minutes of music does a standard audio CD hold according to the original specification?", "minute|minutes", "The standard 120 mm compact disc was designed to hold 74 minutes of music, about 650 MB of data. Capacity was later routinely stretched to 80 minutes.", "Original standard (120 mm disc): 74 minutes of audio; later discs hold up to 80 minutes."),
"technologie-06": ("How many million units of the legendary Nokia 3310 (launched in 2000) were sold worldwide?", "million units|million units", "The Nokia 3310, unveiled in September 2000, became one of the most successful phones ever: 126 million were sold. It remains a byword for indestructibility and a Snake that never gets old.", "Original Nokia 3310 (2000), worldwide sales over its production run."),
"technologie-07": ("How many million chess positions per second could Deep Blue, the computer that beat Garry Kasparov in 1997, evaluate?", "million positions|million positions", "In May 1997 IBM's Deep Blue became the first machine to beat a reigning world chess champion, Garry Kasparov. The upgraded version searched 200 million positions per second – twice as many as the year before, when Kasparov still won.", "The 1997 version (nicknamed Deeper Blue) that won the rematch against Kasparov."),
"technologie-08": ("How many dollars did the first iPhone with 4 GB cost at its US launch in 2007?", "dollar|dollars", "Steve Jobs unveiled the first iPhone in January 2007 and it went on sale in the US in June at $499 (4 GB) and $599 (8 GB). Apple dropped the 4 GB model within months and cut the 8 GB to $399.", "US launch price (June 2007), 4 GB model, with AT&T contract."),
"technologie-09": ("How many words of RAM did the Apollo Guidance Computer, which landed astronauts on the Moon, have?", "word|words", "The Apollo spacecraft computer (Block II) had 2,048 sixteen-bit words of erasable memory – about 4 kB – and 36,864 words of fixed memory whose program was literally woven into wires by hand. It was enough to get to the Moon and back.", "AGC Block II (crewed Apollo flights): 2,048 words of 16-bit erasable memory (≈ 4 kB)."),
"technologie-10": ("How many transistors did the first commercial microprocessor, the Intel 4004 from 1971, contain?", "transistor|transistors", "The Intel 4004, the first commercially produced microprocessor, hit the market in November 1971 with 2,300 transistors. Today's chips have tens of billions.", "Intel 4004 (launched November 1971), transistor count on the chip."),
"technologie-11": ("How many dollars did the first Apple Macintosh (128K) cost when it launched in 1984?", "dollar|dollars", "The first Macintosh cost $2,495 in January 1984, about $7,700 in today's money. It had 128 kB of memory and a nine-inch black-and-white screen.", ""),
"technologie-12": ("How many days after launch did Windows 95 sell its first million copies?", "day|days", "Windows 95 sold a million copies in just four days. Microsoft spent hundreds of millions on the ad campaign built around the Rolling Stones' 'Start Me Up'.", "Launched 24 Aug 1995."),
"technologie-13": ("How many million bitcoins can exist at most according to the protocol?", "million bitcoins|million bitcoins", "There will never be more than 21 million bitcoins. The mining reward halves every 210,000 blocks, so the last bitcoin won't be mined until around 2140.", ""),
"technologie-14": ("How many seconds long is the first video ever uploaded to YouTube ('Me at the zoo', 2005)?", "second|seconds", "The first YouTube video is 19 seconds long: co-founder Jawed Karim, at San Diego Zoo, observes that elephants have really long trunks.", "Uploaded 23 April 2005."),
"technologie-15": ("How many million dollars did Facebook pay for Instagram in 2012?", "million dollars|million dollars", "Facebook paid a billion dollars for Instagram in April 2012 – for an 18-month-old app with no revenue at all.", "$1 billion in cash and stock."),
"technologie-16": ("How many gigabytes was the hard drive of the first iPod from 2001?", "gigabyte|gigabytes", "The first iPod had a 5 GB drive that, according to Apple, held '1,000 songs in your pocket'. Today's phones have a hundred times more.", ""),
"technologie-17": ("How many characters can a single SMS message contain at most?", "character|characters", "An SMS is limited to 160 characters – that's what fitted into the GSM signalling channel. Longer messages are quietly split and sent in parts.", "Standard GSM 7-bit alphabet."),
"technologie-18": ("How many kilometres long is 2Africa, the longest submarine cable in the world?", "kilometre|kilometres", "The 2Africa cable wraps around the whole of Africa and is 45,000 km long – more than the circumference of the Earth. It connects 46 landing stations in 33 countries.", ""),
"technologie-19": ("How many million dollars did Google pay for YouTube in 2006?", "million dollars|million dollars", "Google bought YouTube in November 2006 for $1.65 billion. It looked expensive at the time – today YouTube makes over $30 billion a year.", "$1.65 billion."),
"telo-01": ("How many bones are in one human hand including the wrist (from the carpal bones to the fingertips)?", "bone|bones", "One hand including the wrist has 27 bones: 8 carpals, 5 metacarpals and 14 phalanges. Both hands together hold about a quarter of all the bones in the body.", "Including the 8 carpal bones; without the wrist the hand has 19 bones."),
"telo-02": ("How many pairs of cranial nerves emerge directly from the human brain?", "pair|pairs", "Twelve pairs of cranial nerves emerge from the brain, from the olfactory (I) to the hypoglossal (XII). They handle smell, sight, eye movement, facial expression, hearing and swallowing.", ""),
"telo-03": ("How many days on average does a human red blood cell live before the body breaks it down?", "day|days", "A red blood cell has no nucleus, so its energy lasts on average only 120 days; then the spleen and liver retire it. That's why bone marrow has to keep making new ones non-stop.", "Average lifespan according to Cleveland Clinic."),
"telo-04": ("How many centimetres tall was the tallest man in history, American Robert Wadlow (according to Guinness World Records)?", "centimetre|centimetres", "Robert Pershing Wadlow of Illinois measured a full 272 cm when last measured on 27 June 1940, and was still growing. He died just weeks later, aged 22.", "2.72 m at his last measurement on 27 June 1940."),
"telo-05": ("How many children did the most prolific mother in history, the wife of Russian peasant Feodor Vassilyev, bear according to Guinness World Records?", "child|children", "The wife of Feodor Vassilyev of Shuya gave birth to 69 children in the 18th century, in just 27 confinements: 16 pairs of twins, 7 sets of triplets and 4 sets of quadruplets.", "Highest officially recorded number of children born to one mother (Guinness)."),
"telo-06": ("How many days did Frenchwoman Jeanne Calment, the oldest verified person in history, live?", "day|days", "Jeanne Calment of Arles was born on 21 February 1875 and died on 4 August 1997 aged 122 years and 164 days – 44,724 days. As a girl she reportedly met Vincent van Gogh in a shop.", "122 years and 164 days (21 Feb 1875 – 4 Aug 1997) = 44,724 days."),
"telo-07": ("How many seconds is the men's world record for holding one's breath underwater (Guinness World Records, as of 2025)?", "second|seconds", "Croatian freediver Vitomir Maričić held his breath underwater for 29 minutes 3 seconds – 1,743 seconds – in Opatija on 14 June 2025. He did breathe pure oxygen beforehand, though.", "29 min 3 s = 1,743 s; record from 14 June 2025, oxygen-assisted discipline."),
"telo-08": ("How many teeth does Malaysian Prathab Muniandy, holder of the record for the most teeth in a mouth (Guinness World Records, verified 2023), have?", "tooth|teeth", "Prathab Muniandy of Malaysia has 42 erupted teeth, 10 more than the usual 32, with two more still waiting in his gums. Two dentists verified the record on 28 December 2023.", "Verified 28 Dec 2023; erupted teeth counted."),
"telo-09": ("How many years did the longest recorded attack of hiccups last (Guinness World Records)?", "year|years", "American Charles Osborne started hiccupping in 1922 while weighing a hog and didn't stop until February 1990, 68 years later. He is estimated to have hiccupped more than 420 million times.", "1922 – February 1990."),
"telo-10": ("How many days did the longest recorded sneezing fit last (Guinness World Records)?", "day|days", "Briton Donna Griffiths started sneezing on 13 January 1981 and had her first sneeze-free day on 16 September 1983. In the first year alone she sneezed an estimated million times.", "13 Jan 1981 – 16 Sept 1983 = 976 days; the first sneeze-free day was day 977."),
"telo-11": ("How many kilograms did Jon Brower Minnoch, the heaviest person in medical history according to Guinness World Records, weigh?", "kilogram|kilograms", "Jon Brower Minnoch weighed 635 kg in March 1978. It took 12 firefighters to carry him to hospital, where he lay on two beds lashed together.", "Estimated weight of 635 kg in March 1978."),
"telo-12": ("How many chromosomes does a normal human cell have?", "chromosome|chromosomes", "Humans have 46 chromosomes in 23 pairs. Chimpanzees have 48 – two of ours fused into one long ago.", ""),
"telo-13": ("How many milk teeth does a child have?", "tooth|teeth", "A child has 20 milk teeth; the adult set has 32. Milk teeth start coming through around six months and falling out around age six.", ""),
"telo-14": ("How many millimetres tall was Nepal's Chandra Bahadur Dangi, the shortest adult ever verified by Guinness World Records?", "millimetre|millimetres", "Chandra Bahadur Dangi measured 54.6 cm – shorter than the average three-month-old baby. Guinness recognised the record in 2012, when he was 72.", "54.6 cm."),
"telo-15": ("To what age did Japan's Jiroemon Kimura, the oldest verified man in history, live?", "year|years", "Kimura died in 2013 aged 116 years and 54 days. He is the only man ever verified to reach 116 – women have still outlived him: record holder Jeanne Calment reached 122.", "116 years and 54 days (1897–2013)."),
"telo-16": ("How many bones are in one human foot (including the ankle)?", "bone|bones", "The foot has 26 bones and 33 joints – both feet together make up a quarter of all the bones in the body.", ""),
"telo-17": ("How many days did 17-year-old Randy Gardner stay awake in his famous 1963–64 experiment?", "day|days", "Randy Gardner stayed awake for 11 days and 25 minutes (264 hours). Guinness no longer recognises such attempts, for health reasons.", "11 days and 25 minutes."),
"telo-18": ("How old was Spaniard Maria del Carmen Bousada when she gave birth to twins in 2006 and became the oldest verified mother in the world at the time?", "year|years", "Maria del Carmen Bousada gave birth to twins at 66, a week before her 67th birthday. She had told the clinic in California she was 55.", ""),
"telo-19": ("How many fingers and toes in total was Akshat Saxena of India, the world record holder, born with?", "digit|digits", "Akshat Saxena was born in 2010 with 7 fingers on each hand and 10 toes on each foot – 34 in all. Doctors later surgically removed the extra ones.", ""),
}
